def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    bg=max(set(sum(grid,[])),key=lambda x:sum(r.count(x) for r in grid))
    colors=set(sum(grid,[]))-{bg}
    bar=max(colors,key=lambda x:sum(r.count(x) for r in grid)); p=next(x for x in colors if x!=bar)
    # Edge bars make rectangular beams; each starts at the edge and extends inward.
    for c in range(w):
        if grid[0][c]==bar:
            for r in range(1,h): out[r][c]=p
        if grid[h-1][c]==bar:
            for r in range(h-1): out[r][c]=p
    # Point pattern is a diagonal line; fill its swept triangular region; points become accent 4.
